import{_ as a,c as t,o as n,a3 as i}from"./chunks/framework.BusRvirq.js";const I=JSON.parse('{"title":"SyncInsight 엔터프라이즈 도입 FAQ","description":"기존 대시보드(BI)와의 차이점, 사내 DB 쿼리 보안 가드레일 및 ROI 산출 모델에 대한 자주 묻는 질문","frontmatter":{"title":"SyncInsight 엔터프라이즈 도입 FAQ","shortTitle":"도입 FAQ","category":"거버넌스 & FAQ","sort":7,"description":"기존 대시보드(BI)와의 차이점, 사내 DB 쿼리 보안 가드레일 및 ROI 산출 모델에 대한 자주 묻는 질문","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/syncinsight/enterprise-faq.html"}]]},"headers":[],"relativePath":"syncinsight/enterprise-faq.md","filePath":"ko/syncinsight/enterprise-faq.md","lastUpdated":1789435621000}'),r={name:"syncinsight/enterprise-faq.md"};function s(o,e,l,c,h,d){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="syncinsight-엔터프라이즈-도입-faq" tabindex="-1">SyncInsight 엔터프라이즈 도입 FAQ <a class="header-anchor" href="#syncinsight-엔터프라이즈-도입-faq" aria-label="Permalink to “SyncInsight 엔터프라이즈 도입 FAQ”">​</a></h1><h2 id="_1-기존-bi-도구-대비-차별점" tabindex="-1">1. 기존 BI 도구 대비 차별점 <a class="header-anchor" href="#_1-기존-bi-도구-대비-차별점" aria-label="Permalink to “1. 기존 BI 도구 대비 차별점”">​</a></h2><h3 id="q1-태블로-tableau-나-파워bi-power-bi-가-이미-있는데-syncinsight가-왜-필요한가요" tabindex="-1">Q1. 태블로(Tableau)나 파워BI(Power BI)가 이미 있는데 SyncInsight가 왜 필요한가요? <a class="header-anchor" href="#q1-태블로-tableau-나-파워bi-power-bi-가-이미-있는데-syncinsight가-왜-필요한가요" aria-label="Permalink to “Q1. 태블로(Tableau)나 파워BI(Power BI)가 이미 있는데 SyncInsight가 왜 필요한가요?”">​</a></h3><ul><li><strong>답변</strong>: 기존 BI 도구는 이미 발생한 과거의 데이터를 차트로 시각화하는 데 머무르며, 원인 분석이나 해결책 도출은 여전히 사람(데이터 분석가/기획자)이 직접 수행해야 합니다.</li><li>반면 SyncInsight는 <strong>원인 규명 딥 리서치(Deep Research)</strong>, <strong>멀티 에이전트 토론을 통한 대안 도출</strong>, <strong>What-If 사전 시뮬레이션</strong>, 그리고 관리자 승인 후 <strong>실제 시스템에 액션을 자동 반영(Actionable Execution)</strong>하는 엔드투엔드 의사결정 인텔리전스 플랫폼입니다.</li></ul><hr><h2 id="_2-데이터-거버넌스-및-보안" tabindex="-1">2. 데이터 거버넌스 및 보안 <a class="header-anchor" href="#_2-데이터-거버넌스-및-보안" aria-label="Permalink to “2. 데이터 거버넌스 및 보안”">​</a></h2><h3 id="q2-ai가-사내-데이터베이스를-임의로-수정하거나-장애를-유발할-위험은-없나요" tabindex="-1">Q2. AI가 사내 데이터베이스를 임의로 수정하거나 장애를 유발할 위험은 없나요? <a class="header-anchor" href="#q2-ai가-사내-데이터베이스를-임의로-수정하거나-장애를-유발할-위험은-없나요" aria-label="Permalink to “Q2. AI가 사내 데이터베이스를 임의로 수정하거나 장애를 유발할 위험은 없나요?”">​</a></h3><ul><li><strong>답변</strong>: <ol><li><strong>Strict Read-Only 원칙</strong>: NL2SQL 분석 엔진은 오직 읽기 전용 레플리카(Read Replica)에만 접근 권한이 부여되며, <code>INSERT</code>, <code>UPDATE</code>, <code>DELETE</code>, <code>DROP</code> 등 모든 변경 쿼리는 파서 레벨에서 원천 차단됩니다.</li><li><strong>쿼리 복잡도 가드레일</strong>: 과도한 풀스캔이나 비효율적인 조인으로 인한 DB 부하를 방지하기 위해 쿼리 타임아웃(최대 10초) 및 강제 <code>LIMIT</code>(기본 1,000건) 절이 자동 주입됩니다.</li></ol></li></ul><h3 id="q3-도출된-액션이-잘못되었을-때-되돌릴-수-있나요" tabindex="-1">Q3. 도출된 액션이 잘못되었을 때 되돌릴 수 있나요? <a class="header-anchor" href="#q3-도출된-액션이-잘못되었을-때-되돌릴-수-있나요" aria-label="Permalink to “Q3. 도출된 액션이 잘못되었을 때 되돌릴 수 있나요?”">​</a></h3><ul><li><strong>답변</strong>: 네, SyncInsight가 발행하는 모든 비즈니스 액션은 <strong>HITL(Human-in-the-Loop) 관리자 사전 승인</strong>을 거쳐야만 프로덕션에 적용되며, 적용 즉시 이전 상태의 스냅샷과 롤백 스크립트가 자동 보관되어 1클릭 복구가 가능합니다.</li></ul>',10)])])}const p=a(r,[["render",s]]);export{I as __pageData,p as default};
